//! 构建期一致性检查（代码审查 M3、安全审查 X-3），只有单测：
//! • lib.rs 里 generate_handler! 注册的命令 = commands.rs 的名单；
//! • 每个命令在 permissions/autogenerated/ 下都有生成的权限文件（这个目录提交进仓库，CI 编译后 diff 必须为空）；
//! • capabilities 里只授予名单里的命令，并且按窗口核对：哪些命令只给哪个窗口。

#[cfg(test)]
mod tests {
    use crate::commands::COMMANDS;
    use std::collections::BTreeSet;

    const LIB: &str = include_str!("lib.rs");
    const CAPS: [(&str, &str); 3] = [
        ("main", include_str!("../capabilities/main.json")),
        ("auth", include_str!("../capabilities/auth.json")),
        ("quick-add", include_str!("../capabilities/quick-add.json")),
    ];

    /// 每个命令只给哪些窗口
    fn expected_windows(cmd: &str) -> &'static [&'static str] {
        match cmd {
            "session_get" | "session_remove" | "open_external" | "auth_window_open" | "main_show" | "app_update" | "hotkey_get" | "hotkey_set" => {
                &["main"]
            }
            "session_set" => &["main", "auth"],
            "auth_done" | "auth_open_signup" => &["auth"],
            "quick_add_submit" | "quick_add_hide" => &["quick-add"],
            _ => &[],
        }
    }

    fn handler_commands() -> BTreeSet<String> {
        let start = LIB.find("generate_handler![").expect("lib.rs 里找不到 generate_handler!") + "generate_handler![".len();
        let end = start + LIB[start..].find(']').expect("generate_handler! 没有闭合");
        LIB[start..end].split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect()
    }

    #[test]
    fn 注册的命令和名单一致() {
        let listed: BTreeSet<String> = COMMANDS.iter().map(|s| s.to_string()).collect();
        assert_eq!(handler_commands(), listed);
        assert_eq!(listed.len(), COMMANDS.len(), "名单里有重复");
    }

    #[test]
    fn 每个命令都有生成的权限文件() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("permissions/autogenerated");
        let have: BTreeSet<String> = std::fs::read_dir(&dir)
            .expect("permissions/autogenerated 不存在")
            .filter_map(|e| e.ok()?.file_name().into_string().ok())
            .filter_map(|n| n.strip_suffix(".toml").map(String::from))
            .collect();
        let want: BTreeSet<String> = COMMANDS.iter().map(|s| s.to_string()).collect();
        assert_eq!(have, want, "权限文件和命令名单对不上（重新编译并提交 permissions/autogenerated）");
    }

    #[test]
    fn 各窗口只授予该给的命令() {
        for (win, raw) in CAPS {
            let v: serde_json::Value = serde_json::from_str(raw).unwrap();
            assert_eq!(v["windows"], serde_json::json!([win]), "{win}.json 只能给 {win} 一个窗口");
            assert!(v.get("remote").is_none(), "{win}.json 不许开 remote");
            for p in v["permissions"].as_array().unwrap() {
                let p = p.as_str().unwrap();
                if p.contains(':') {
                    // 插件和核心权限：只许这几条
                    let ok = matches!(
                        (win, p),
                        ("main", "core:event:allow-listen")
                            | ("main", "core:event:allow-unlisten")
                            | ("main", "autostart:allow-enable")
                            | ("main", "autostart:allow-disable")
                            | ("main", "autostart:allow-is-enabled")
                    );
                    assert!(ok, "{win}.json 不该有 {p}");
                    continue;
                }
                let cmd = p.strip_prefix("allow-").unwrap_or_else(|| panic!("{win}.json 的 {p} 不是 allow-<命令>")).replace('-', "_");
                assert!(COMMANDS.contains(&cmd.as_str()), "{win}.json 授予了名单外的 {p}");
                assert!(expected_windows(&cmd).contains(&win), "{p} 不该给 {win}");
            }
        }
        // 反过来：每个命令都授予了该给的窗口
        for cmd in COMMANDS {
            for win in expected_windows(cmd) {
                let raw = CAPS.iter().find(|(w, _)| w == win).unwrap().1;
                let perm = format!("\"allow-{}\"", cmd.replace('_', "-"));
                assert!(raw.contains(&perm), "{win}.json 缺 {perm}");
            }
        }
    }
}
